  ('t4', 2, 'Brendan Eich entwarf die erste Version von JavaScript bei Netscape in rund zehn Tagen.', '{"en":{"explanation":"Brendan Eich designed the first version of JavaScript at Netscape in about ten days."}}'::jsonb),
  ('t5', 1, 'Ein generatives Modell, das vorab auf großen Textmengen trainiert wurde und auf der Transformer-Architektur beruht.', '{"en":{"explanation":"A generative model that was pre-trained on large amounts of text and is based on the transformer architecture."}}'::jsonb),
  ('t6', 1, 'Das Paper von Vaswani und Kollegen ersetzte rekurrente Netze durch Aufmerksamkeitsmechanismen – die Grundlage heutiger Sprachmodelle.', '{"en":{"explanation":"The paper by Vaswani and colleagues replaced recurrent networks with attention mechanisms – the basis of today''s language models."}}'::jsonb),
  ('t7', 1, 'Modelle zerlegen Text in Tokens und sagen Schritt für Schritt das nächste Token vorher.', '{"en":{"explanation":"Models split text into tokens and predict the next token step by step."}}'::jsonb),
  ('t8', 1, 'Gordon Moore beobachtete 1965, dass sich die Transistordichte regelmäßig verdoppelt – später meist mit etwa zwei Jahren angegeben.', '{"en":{"explanation":"In 1965 Gordon Moore observed that transistor density doubles regularly – later usually stated as about every two years."}}'::jsonb),
  ('t9', 0, 'Beim Turing-Test soll ein Mensch im Gespräch nicht mehr unterscheiden können, ob er mit Mensch oder Maschine schreibt.', '{"en":{"explanation":"In the Turing test, a person in conversation should no longer be able to tell whether they are writing with a human or a machine."}}'::jsonb),
