  ('tm2', 1, 'Der Modus speichert nur keinen Verlauf auf dem eigenen Gerät. Websites und Internetanbieter sehen die Zugriffe weiterhin.', '{"en":{"explanation":"The mode merely stops history being saved on your own device. Websites and internet providers can still see your activity."}}'::jsonb),
  ('tf4', 0, 'Das CERN hat die Seite von 1991 unter ihrer ursprünglichen Adresse info.cern.ch wiederhergestellt.', '{"en":{"explanation":"CERN has restored the 1991 page at its original address, info.cern.ch."}}'::jsonb),
  ('tm3', 1, 'Sensorgröße, Objektiv und Bildverarbeitung sind für die Bildqualität meist wichtiger als die reine Pixelzahl.', '{"en":{"explanation":"Sensor size, lens and image processing usually matter more for image quality than the pixel count alone."}}'::jsonb),
  ('hm2', 1, 'Dass die Erde eine Kugel ist, war unter Gebildeten seit der Antike bekannt und wurde auch im Mittelalter gelehrt.', '{"en":{"explanation":"That the Earth is a sphere had been known to educated people since antiquity and was taught in the Middle Ages too."}}'::jsonb),
  ('hm3', 1, 'Mit etwa 1,68 Metern war er für seine Zeit durchschnittlich groß. Der Mythos geht auf britische Karikaturen und unterschiedliche Maßeinheiten zurück.', '{"en":{"explanation":"At about 1.68 metres he was of average height for his time. The myth goes back to British caricatures and differing units of measurement."}}'::jsonb),
  ('hf4', 0, 'In L’Anse aux Meadows in Neufundland wurde eine Wikingersiedlung aus der Zeit um das Jahr 1000 gefunden.', '{"en":{"explanation":"A Viking settlement from around the year 1000 was found at L''Anse aux Meadows in Newfoundland."}}'::jsonb),
  ('gm2', 1, 'Sie legen bei Gefahr manchmal Hals und Kopf flach auf den Boden – aus der Ferne sieht das so aus.', '{"en":{"explanation":"When threatened they sometimes lay their neck and head flat on the ground – from a distance it looks that way."}}'::jsonb),
  ('gf2', 0, 'Im Blitzkanal entstehen bis zu 30.000 Grad Celsius, die Sonnenoberfläche hat rund 5.500 Grad.', '{"en":{"explanation":"Temperatures in the lightning channel reach up to 30,000 degrees Celsius; the Sun''s surface is about 5,500 degrees."}}'::jsonb),
  ('gm3', 1, 'In Versuchen merkten sich Goldfische Aufgaben über Wochen und Monate.', '{"en":{"explanation":"In experiments, goldfish remembered tasks for weeks and months."}}'::jsonb),
  ('em2', 1, 'Gibt es mehr Geld, aber nicht mehr Waren, steigen vor allem die Preise.', '{"en":{"explanation":"If there is more money but not more goods, it is mainly prices that rise."}}'::jsonb),
  ('ef2', 0, 'Im Königreich Lydien in der heutigen Türkei entstanden im 7. Jahrhundert v. Chr. die ersten Münzen.', '{"en":{"explanation":"The first coins were made in the 7th century BC in the kingdom of Lydia, in what is now Turkey."}}'::jsonb),
  ('em3', 1, 'Höhere Renditechancen gehen grundsätzlich mit höherem Risiko einher. Wer beides ohne Haken verspricht, ist oft ein Betrüger.', '{"en":{"explanation":"Higher potential returns generally come with higher risk. Anyone promising both with no catch is often a fraudster."}}'::jsonb),
  ('cm2', 1, 'Frankenstein ist der Name des Wissenschaftlers Victor Frankenstein. Sein Geschöpf bleibt im Roman namenlos.', '{"en":{"explanation":"Frankenstein is the name of the scientist, Victor Frankenstein. His creature remains nameless in the novel."}}'::jsonb),
  ('cf2', 0, 'Sie wurden dort über mehr als tausend Jahre zu Ehren des Gottes Zeus ausgetragen.', '{"en":{"explanation":"They were held there for more than a thousand years in honour of the god Zeus."}}'::jsonb),
  ('cm3', 1, 'Die Melodie stammt von Franz Xaver Gruber, der Text von Joseph Mohr. Uraufgeführt wurde es 1818 bei Salzburg.', '{"en":{"explanation":"The melody is by Franz Xaver Gruber and the words by Joseph Mohr. It was first performed near Salzburg in 1818."}}'::jsonb),
  ('q-v-iss-nacht', 0, 'Etwa 90 Minuten – die Besatzung erlebt deshalb rund 16 Sonnenaufgänge am Tag.', '{"en":{"explanation":"About 90 minutes – so the crew sees around 16 sunrises a day."}}'::jsonb),
  ('q-v-saturn-v', 0, 'Die dreistufige Saturn V startete zwischen 1967 und 1973 insgesamt 13 Mal.', '{"en":{"explanation":"The three-stage Saturn V launched 13 times between 1967 and 1973."}}'::jsonb),
  ('q-v-aldrin', 0, 'Michael Collins blieb währenddessen im Kommandomodul in der Mondumlaufbahn.', '{"en":{"explanation":"Meanwhile, Michael Collins stayed in the command module in lunar orbit."}}'::jsonb),
  ('q-v-ingenuity', 0, 'Ingenuity reiste zusammen mit dem Rover Perseverance zum Mars.', '{"en":{"explanation":"Ingenuity travelled to Mars together with the rover Perseverance."}}'::jsonb),
  ('q-v-sonne', 0, 'Im Kern verschmilzt Wasserstoff zu Helium – daher stammt die Energie der Sonne.', '{"en":{"explanation":"In the core, hydrogen fuses into helium – that is where the Sun''s energy comes from."}}'::jsonb),
  ('q-v-hurrikan', 0, 'Um das Auge liegt die Augenwand mit den höchsten Windgeschwindigkeiten.', '{"en":{"explanation":"Around the eye lies the eyewall, with the highest wind speeds."}}'::jsonb)
insert into public.videos (id, category_id, title, hook, description, video_url, thumbnail_url, duration_seconds, has_audio, captions, creator_name, format, sources, published_at, tags, quiz_question_id, verification_status, status, min_age, start_seconds, end_seconds, license, translations) values
  ('v-venus', 'science', 'Auf der Venus ist ein Tag länger als ein Jahr', '243 Erdtage für eine Drehung, nur 225 für einen Umlauf um die Sonne.', 'Die Venus dreht sich extrem langsam – und noch dazu rückwärts. Deshalb dauert eine Drehung um die eigene Achse länger als ein kompletter Umlauf um die Sonne.', '/clips/v-venus.mp4', null, 7.27, true, '["Die Venus dreht sich so langsam,","dass ein Tag dort länger dauert","als ein ganzes Jahr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Venus (Planet)","url":"https://de.wikipedia.org/wiki/Venus_(Planet)"}]'::jsonb, '2026-10-09T12:00:00Z', array['Planeten', 'Sonnensystem']::text[], 'q-v-venus', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-kleopatra', 'history', 'Kleopatra lebte näher an der Mondlandung als am Pyramidenbau', 'Das alte Ägypten dauerte so lange, dass seine Anfänge für Kleopatra schon Altertum waren.', 'Die Cheops-Pyramide entstand um 2560 v. Chr. Kleopatra starb 30 v. Chr. – rund 2500 Jahre später. Bis zur Mondlandung 1969 vergingen danach nur etwa 2000 Jahre.', '/clips/v-kleopatra.mp4', null, 6.91, true, '["Kleopatra lebte näher","an der Mondlandung","als am Bau der großen Pyramide."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Kleopatra VII.","url":"https://de.wikipedia.org/wiki/Kleopatra_VII."},{"name":"Wikipedia: Cheops-Pyramide","url":"https://de.wikipedia.org/wiki/Cheops-Pyramide"}]'::jsonb, '2026-10-08T12:00:00Z', array['Ägypten', 'Zeitgefühl']::text[], 'q-v-kleopatra', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-apollo', 'technology', 'Zum Mond mit 4 Kilobyte Arbeitsspeicher', 'Der Apollo-Bordcomputer hatte millionenfach weniger Speicher als ein Smartphone.', 'Der Apollo Guidance Computer hatte 2048 Wörter beschreibbaren Speicher, etwa 4 Kilobyte. Ein Smartphone mit 8 Gigabyte hat rund zwei Millionen Mal so viel.', '/clips/v-apollo.mp4', null, 11.3, true, '["Der Computer, der Menschen zum Mond brachte,","hatte rund vier Kilobyte Arbeitsspeicher.","Ein Smartphone hat millionenfach mehr."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Apollo Guidance Computer","url":"https://de.wikipedia.org/wiki/Apollo_Guidance_Computer"}]'::jsonb, '2026-10-10T12:00:00Z', array['Raumfahrt', 'Computer']::text[], 'q-v-apollo', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-luft', 'science', 'Was du gerade einatmest, ist vor allem Stickstoff', 'Luft besteht zu etwa 78 % aus Stickstoff und nur zu 21 % aus Sauerstoff.', 'Trockene Luft enthält rund 78 % Stickstoff, 21 % Sauerstoff und knapp 1 % Argon. Kohlendioxid macht nur einen Bruchteil eines Prozents aus.', '/clips/v-luft.mp4', null, 9.63, true, '["Die Luft, die du atmest,","besteht nur zu einem Fünftel aus Sauerstoff.","Der größte Teil ist Stickstoff."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erdatmosphäre","url":"https://de.wikipedia.org/wiki/Erdatmosphäre"}]'::jsonb, '2026-10-05T12:00:00Z', array['Atmosphäre', 'Chemie']::text[], 'q-v-luft', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-ozean', 'earth', 'Der blaue Planet: mehr Wasser als Land', 'Rund 71 % der Erdoberfläche sind von Wasser bedeckt.', 'Ozeane und Meere bedecken etwa 71 % der Erdoberfläche. Landflächen machen rund 29 % aus – weniger als ein Drittel.', '/clips/v-ozean.mp4', null, 9.26, true, '["Rund 71 Prozent der Erdoberfläche","sind von Wasser bedeckt.","Land macht weniger als ein Drittel aus."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: Erde","url":"https://de.wikipedia.org/wiki/Erde"}]'::jsonb, '2026-10-07T12:00:00Z', array['Ozeane', 'Geografie']::text[], 'q-v-ozean', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-oxford', 'history', 'Oxford ist älter als das Reich der Azteken', 'In Oxford wurde schon um 1096 gelehrt, Tenochtitlan entstand erst um 1325.', 'Die Lehre in Oxford ist seit etwa 1096 belegt. Tenochtitlan, die Hauptstadt der Azteken, wurde um 1325 gegründet – mehr als zwei Jahrhunderte später.', '/clips/v-oxford.mp4', null, 7.04, true, '["In Oxford wurde schon gelehrt,","als es die Hauptstadt der Azteken","noch gar nicht gab."]'::jsonb, 'Wunder Redaktion', 'animated_fact', '[{"name":"Wikipedia: University of Oxford","url":"https://de.wikipedia.org/wiki/University_of_Oxford"},{"name":"Wikipedia: Tenochtitlan","url":"https://de.wikipedia.org/wiki/Tenochtitlan"}]'::jsonb, '2026-10-03T12:00:00Z', array['Mittelalter', 'Zeitgefühl']::text[], 'q-v-oxford', 'unverified', 'archived', 10, null, null, null, '{}'::jsonb),
  ('v-iss-nacht', 'earth', 'Die Erde bei Nacht – gesehen von der Raumstation', 'Die ISS umrundet die Erde etwa alle 90 Minuten – rund 16 Mal am Tag.', 'Die Internationale Raumstation fliegt in rund 400 Kilometern Höhe mit etwa 28.000 km/h. Der farbige Schimmer über dem Horizont ist das Nachthimmelsleuchten der oberen Atmosphäre.', 'https://images-assets.nasa.gov/video/GSFC_20180124_m12825_ISS_Airglow/GSFC_20180124_m12825_ISS_Airglow~small.mp4', null, 10, false, '["So sieht die Erde nachts aus dem All aus.","Die Raumstation fliegt mit rund 28.000 km/h.","Alle 90 Minuten umrundet sie die Erde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20180124_m12825_ISS_Airglow"}]'::jsonb, '2026-10-12T12:00:00Z', array['ISS', 'Raumfahrt', 'Atmosphäre']::text[], 'q-v-iss-nacht', 'unverified', 'published', 10, 2, 12, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"Earth at night – seen from the space station","hook":"The ISS circles the Earth about every 90 minutes – roughly 16 times a day.","description":"The International Space Station flies at an altitude of about 400 kilometres at roughly 28,000 km/h. The coloured shimmer above the horizon is airglow in the upper atmosphere.","captions":["This is what Earth looks like at night from space.","The space station travels at about 28,000 km/h.","It circles the Earth every 90 minutes."]}}'::jsonb),
  ('v-saturn-v', 'history', 'Der Start von Apollo 11', 'Am 16. Juli 1969 hob die Saturn V ab – vier Tage später landeten Menschen auf dem Mond.', 'Die Saturn V war rund 110 Meter hoch und ist bis heute eine der stärksten Raketen, die je geflogen sind. An Bord von Apollo 11: Neil Armstrong, Buzz Aldrin und Michael Collins.', 'https://images-assets.nasa.gov/video/Apollo_11_Intro_720p/Apollo_11_Intro_720p~small.mp4', null, 5.5, false, '["16. Juli 1969: Apollo 11 startet.","Die Saturn-V-Rakete ist 110 Meter hoch.","Ihr Ziel: der Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Apollo_11_Intro_720p"}]'::jsonb, '2026-10-11T12:00:00Z', array['Apollo', 'Raumfahrt', 'Mondlandung']::text[], 'q-v-saturn-v', 'unverified', 'published', 10, 22, 27.5, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"The launch of Apollo 11","hook":"On 16 July 1969 the Saturn V lifted off – four days later humans landed on the Moon.","description":"The Saturn V was about 110 metres tall and remains one of the most powerful rockets ever flown. On board Apollo 11: Neil Armstrong, Buzz Aldrin and Michael Collins.","captions":["16 July 1969: Apollo 11 lifts off.","The Saturn V rocket is 110 metres tall.","Its destination: the Moon."]}}'::jsonb),
  ('v-aldrin', 'history', 'Der zweite Mensch auf dem Mond', 'Buzz Aldrin stieg rund 19 Minuten nach Neil Armstrong die Leiter der Mondfähre hinab.', 'Originalaufnahme der Fernsehübertragung vom 20. Juli 1969 in restaurierter Fassung. Rund 600 Millionen Menschen verfolgten die Mondlandung live.', 'https://images-assets.nasa.gov/video/Buzz_Descends_Comparison__720p/Buzz_Descends_Comparison__720p~small.mp4', null, 10, false, '["20. Juli 1969, Meer der Ruhe.","Buzz Aldrin steigt die Leiter hinab.","Er ist der zweite Mensch auf dem Mond."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/Buzz_Descends_Comparison__720p"}]'::jsonb, '2026-10-10T12:00:00Z', array['Apollo', 'Mondlandung']::text[], 'q-v-aldrin', 'unverified', 'published', 10, 24, 34, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"The second human on the Moon","hook":"Buzz Aldrin climbed down the lunar module''s ladder about 19 minutes after Neil Armstrong.","description":"Original footage from the television broadcast of 20 July 1969 in a restored version. Around 600 million people watched the Moon landing live.","captions":["20 July 1969, Sea of Tranquility.","Buzz Aldrin climbs down the ladder.","He is the second human on the Moon."]}}'::jsonb),
  ('v-ingenuity', 'technology', 'Ein Hubschrauber auf dem Mars', 'Ingenuity gelang 2021 der erste motorisierte Flug auf einem anderen Planeten.', 'Animation der NASA. Die Marsluft ist rund hundertmal dünner als die der Erde, deshalb drehen sich die Rotoren von Ingenuity mit etwa 2.400 Umdrehungen pro Minute. Geplant waren fünf Flüge – es wurden 72.', 'https://images-assets.nasa.gov/video/JPL-20200429-TECHf-0002-Mars%20Helicopter%20Animation/JPL-20200429-TECHf-0002-Mars%20Helicopter%20Animation~small.mp4', null, 10, false, '["Das ist Ingenuity, ein Hubschrauber für den Mars.","Die Luft dort ist hundertmal dünner als auf der Erde.","Trotzdem flog er 72 Mal."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/JPL-20200429-TECHf-0002-Mars%20Helicopter%20Animation"}]'::jsonb, '2026-10-09T12:00:00Z', array['Mars', 'Raumfahrt', 'Robotik']::text[], 'q-v-ingenuity', 'unverified', 'published', 10, 62, 72, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"A helicopter on Mars","hook":"In 2021 Ingenuity made the first powered flight on another planet.","description":"NASA animation. The Martian air is about a hundred times thinner than Earth''s, so Ingenuity''s rotors spin at around 2,400 revolutions per minute. Five flights were planned – it made 72.","captions":["This is Ingenuity, a helicopter built for Mars.","The air there is a hundred times thinner than on Earth.","It still flew 72 times."]}}'::jsonb),
  ('v-sonne', 'science', 'Unsere Sonne in Bewegung', 'Die Sonne enthält mehr als 99,8 Prozent der gesamten Masse unseres Sonnensystems.', 'Zeitrafferaufnahmen des Sonnenobservatoriums SDO im ultravioletten Licht. Die Sonne ist eine Kugel aus heißem Plasma und besteht vor allem aus Wasserstoff und Helium.', 'https://images-assets.nasa.gov/video/GSFC_20160212_SDO_m12144_Year6/GSFC_20160212_SDO_m12144_Year6~small.mp4', null, 10, false, '["Das ist unsere Sonne im ultravioletten Licht.","Ihre Oberfläche ist ständig in Bewegung.","Sie enthält 99,8 Prozent der Masse des Sonnensystems."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/GSFC_20160212_SDO_m12144_Year6"}]'::jsonb, '2026-10-08T12:00:00Z', array['Sonne', 'Astronomie']::text[], 'q-v-sonne', 'unverified', 'published', 10, 40, 50, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"Our Sun in motion","hook":"The Sun contains more than 99.8 percent of the total mass of our solar system.","description":"Time-lapse footage from the Solar Dynamics Observatory in ultraviolet light. The Sun is a ball of hot plasma made mostly of hydrogen and helium.","captions":["This is our Sun in ultraviolet light.","Its surface is constantly in motion.","It contains 99.8 percent of the solar system''s mass."]}}'::jsonb),
  ('v-hurrikan', 'earth', 'Ein Hurrikan aus dem All', 'Im Auge eines Hurrikans ist es fast windstill – ringsum toben die stärksten Winde.', 'Hurrikan Dorian am 1. September 2019, aufgenommen von Kameras an der Internationalen Raumstation. Tropische Wirbelstürme entstehen über warmem Meerwasser ab etwa 26 Grad.', 'https://images-assets.nasa.gov/video/jsc2019m000805_Hurricane_Dorian_190901/jsc2019m000805_Hurricane_Dorian_190901~small.mp4', null, 10, false, '["Hurrikan Dorian, gefilmt von der Raumstation.","In der Mitte liegt das fast windstille Auge.","Ringsum toben die stärksten Winde."]'::jsonb, 'NASA', 'footage', '[{"name":"NASA Image and Video Library","url":"https://images.nasa.gov/details/jsc2019m000805_Hurricane_Dorian_190901"}]'::jsonb, '2026-10-07T12:00:00Z', array['Wetter', 'Hurrikan', 'ISS']::text[], 'q-v-hurrikan', 'unverified', 'published', 10, 100, 110, 'NASA-Material, gemeinfrei (keine Billigung durch die NASA)', '{"en":{"title":"A hurricane seen from space","hook":"The eye of a hurricane is almost calm – the strongest winds rage all around it.","description":"Hurricane Dorian on 1 September 2019, filmed by cameras on the International Space Station. Tropical cyclones form over warm sea water of about 26 degrees or more.","captions":["Hurricane Dorian, filmed from the space station.","In the middle lies the almost windless eye.","The strongest winds rage all around it."]}}'::jsonb)
